package com.cinebook.api;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/bookings") public class BookingController{
 private final JdbcTemplate db;public BookingController(JdbcTemplate d){db=d;}record Request(@Positive long showId,@NotEmpty List<Long> seatIds){}
 @PostMapping @Transactional Map<String,Object> book(@Valid @RequestBody Request r,Authentication a){long uid=((Number)a.getDetails()).longValue();if(new HashSet<>(r.seatIds()).size()!=r.seatIds().size())throw new IllegalArgumentException("Duplicate seats");var sh=db.queryForMap("select screen_id,base_price from show_time where id=? and starts_at>now() for update",r.showId());var seats=db.queryForList("select id from cinema_seat where screen_id=? and id in ("+String.join(",",Collections.nCopies(r.seatIds().size(),"?"))+")",prepend(((Number)sh.get("screen_id")).longValue(),r.seatIds()));if(seats.size()!=r.seatIds().size())throw new IllegalArgumentException("Invalid seat selection");for(Long seat:r.seatIds()){Integer n=db.queryForObject("select count(*) from booking_seat bs join booking b on b.id=bs.booking_id where bs.seat_id=? and b.show_id=? and b.status='CONFIRMED'",Integer.class,seat,r.showId());if(n!=null&&n>0)throw new IllegalArgumentException("Seat already booked; refresh and retry");}
 double total=((Number)sh.get("base_price")).doubleValue()*r.seatIds().size();String code="CB"+UUID.randomUUID().toString().replace("-","").substring(0,10).toUpperCase();Long bid=db.queryForObject("insert into booking(booking_code,user_id,show_id,status,total_amount) values(?,?,?,'CONFIRMED',?) returning id",Long.class,code,uid,r.showId(),total);for(Long seat:r.seatIds())db.update("insert into booking_seat(booking_id,seat_id) values(?,?)",bid,seat);db.update("insert into payment(booking_id,provider,status,amount) values(?,'DEMO','PAID',?)",bid,total);return Map.of("id",bid,"bookingCode",code,"totalAmount",total,"status","CONFIRMED","paymentMode","DEMO");}
 Object[] prepend(long screen,List<Long> seats){Object[] a=new Object[seats.size()+1];a[0]=screen;for(int i=0;i<seats.size();i++)a[i+1]=seats.get(i);return a;}
 @GetMapping("/my") List<Map<String,Object>> mine(Authentication a){return db.queryForList("select b.id,b.booking_code,b.status,b.total_amount,b.created_at,m.title,st.starts_at from booking b join show_time st on st.id=b.show_id join movie m on m.id=st.movie_id where b.user_id=? order by b.created_at desc",((Number)a.getDetails()).longValue());}
}
